<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import UiDialog from '@/components/ui/UiDialog.vue'
import OnboardingPreview from '@/components/design/OnboardingPreview.vue'
import { onboardingDemo } from '@/lib/onboarding-demo'

type Room = { id: number; name: string; floor: string; area: number; price: number; residents: number; capacity: number; state: string; photo: string; pending?: boolean }
const route = useRoute(), router = useRouter()
const screens = [
  { id: 'overview', label: 'Chủ trọ · Tổng quan' }, { id: 'rooms', label: 'Chủ trọ · Phòng' },
  { id: 'approvals', label: 'Chủ trọ · Duyệt thành viên' }, { id: 'invite', label: 'Chủ trọ · Mã mời' },
  { id: 'register', label: 'Đăng ký tài khoản' }, { id: 'start', label: 'Chọn nhu cầu' }, { id: 'create', label: 'Tạo khu trọ' },
  { id: 'join', label: 'Nhập mã khu trọ' }, { id: 'status', label: 'Trạng thái người thuê' },
  { id: 'invoice', label: 'Người thuê · Hóa đơn mẫu' }, { id: 'find', label: 'Tìm phòng' }, { id: 'booking', label: 'Đặt lịch xem' }, { id: 'rental-return', label: 'Gửi yêu cầu thuê' }
]
const extraScreens = ['overview', 'approvals', 'invite', 'register', 'start', 'create', 'join', 'status']
const isOwner = computed(() => ['overview', 'rooms', 'approvals', 'invite'].includes(screen.value))
const screenLabel = computed(() => screens.find(s => s.id === screen.value)?.label ?? 'Phòng')
function receiveRoom(name: string) { const room = rooms.value.find(r => r.name === name); if (room && !room.pending && room.state === 'Còn trống') { room.residents = 1; room.state = 'Đang ở' } }

const screen = computed(() => screens.some(s => s.id === route.query.screen) ? String(route.query.screen) : 'overview')
const go = (id: string) => router.replace({ path: '/preview-v2', query: { screen: id } })
const collapsed = ref(false)
function toggleMenu() { if (window.matchMedia('(max-width: 900px)').matches) menu.value = !menu.value; else collapsed.value = !collapsed.value }
const menu = ref(false), search = ref(''), filter = ref(''), budget = ref(''), notice = ref('')
const rooms = ref<Room[]>([
  { id: 1, name: 'A101', floor: 'Tầng 1', area: 24, price: 2800000, residents: 2, capacity: 2, state: 'Đang ở', photo: 'room-light.jpg' },
  { id: 2, name: 'A102', floor: 'Tầng 1', area: 28, price: 3200000, residents: 0, capacity: 2, state: 'Còn trống', photo: 'room-studio.jpg' },
  { id: 3, name: 'B201', floor: 'Tầng 2', area: 24, price: 2800000, residents: 1, capacity: 2, state: 'Đang ở', photo: 'room-light.jpg' },
  { id: 4, name: 'B202', floor: 'Tầng 2', area: 30, price: 3500000, residents: 0, capacity: 3, state: 'Còn trống', photo: 'room-light.jpg' },
  { id: 5, name: 'B203', floor: 'Tầng 2', area: 22, price: 2500000, residents: 0, capacity: 2, state: 'Bảo trì', photo: 'room-studio.jpg' },
  { id: 6, name: 'C301', floor: 'Tầng 3', area: 26, price: 3000000, residents: 0, capacity: 2, state: 'Còn trống', photo: 'room-studio.jpg' },
])
const money = (n: number) => new Intl.NumberFormat('vi-VN').format(n) + ' đ'
const visible = computed(() => rooms.value.filter(r => r.name.toLowerCase().includes(search.value.toLowerCase()) && (!filter.value || r.state === filter.value)))
const available = computed(() => rooms.value.filter(r => r.state === 'Còn trống' && !r.pending && (!budget.value || r.price <= Number(budget.value))))
const selected = ref<Room>(rooms.value[1]!)
const modal = ref<'view' | 'edit' | 'delete' | 'new' | 'payment' | 'rental' | ''>('')
const draftName = ref(''), draftPrice = ref(0), error = ref('')
const modalTitle = computed(() => ({ view: `Phòng ${selected.value.name}`, edit: `Sửa phòng ${selected.value.name}`, delete: `Xóa phòng ${selected.value.name}`, new: 'Thêm phòng', payment: 'Thanh toán chuyển khoản', rental: 'Gửi yêu cầu thuê phòng' })[modal.value || 'view'])
function open(kind: typeof modal.value, room?: Room) {
  if (room) selected.value = room
  draftName.value = kind === 'new' ? '' : selected.value.name
  draftPrice.value = kind === 'new' ? 2800000 : selected.value.price
  error.value = ''; modal.value = kind
}
function save() {
  if (!draftName.value.trim() || !Number.isFinite(draftPrice.value) || draftPrice.value < 0) { error.value = 'Điền số phòng và giá thuê hợp lệ.'; return }
  if (rooms.value.some(r => r.name.toLowerCase() === draftName.value.trim().toLowerCase() && (modal.value === 'new' || r.id !== selected.value.id))) { error.value = 'Số phòng đã tồn tại.'; return }
  if (modal.value === 'new') rooms.value.push({ id: Date.now(), name: draftName.value.trim(), price: draftPrice.value, floor: 'Tầng 1', area: 24, capacity: 2, residents: 0, state: 'Còn trống', photo: 'room-light.jpg' })
  else { selected.value.name = draftName.value.trim(); selected.value.price = draftPrice.value }
  notice.value = 'Đã lưu phòng trong bản xem thử.'; modal.value = ''
}
function queueDelete() { selected.value.pending = true; notice.value = `Phòng ${selected.value.name} đang chờ xóa. Bạn có thể hủy ngay tại dòng phòng.`; modal.value = '' }
function book(room: Room) { selected.value = room; sent.value = false; step.value = 1; if (!onboardingDemo.registered) { onboardingDemo.afterRegister = 'booking'; void go('register') } else void go('booking') }
const rentalDate = ref(''), rentalPeople = ref(1)
function sendRental() {
  error.value = ''
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())
  if (!rentalDate.value || rentalDate.value < today || !Number.isInteger(rentalPeople.value) || rentalPeople.value < 1 || rentalPeople.value > selected.value.capacity) { error.value = 'Chọn ngày từ hôm nay và số người phù hợp sức chứa phòng.'; return }
  if (selected.value.pending || selected.value.state !== 'Còn trống') { error.value = 'Phòng không còn nhận yêu cầu mới.'; return }
  if (!onboardingDemo.rentalRequests.some(r => r.room === selected.value.name)) onboardingDemo.rentalRequests.push({ room: selected.value.name, date: rentalDate.value, people: rentalPeople.value })
  modal.value = ''; void go('status')
}
function requestRental() {
  if (!onboardingDemo.registered) { onboardingDemo.afterRegister = 'rental-return'; void go('register') }
  else { error.value = ''; modal.value = 'rental' }
}
const step = ref(1), day = ref(''), time = ref(''), guest = ref(''), phone = ref(''), sent = ref(false)
const dates = Array.from({ length: 5 }, (_, n) => { const d = new Date(); d.setDate(d.getDate() + n + 1); return { value: d.toISOString().slice(0,10), label: new Intl.DateTimeFormat('vi-VN', { weekday: 'short', day: '2-digit', month: '2-digit' }).format(d) } })
const dayLabel = computed(() => dates.find(d => d.value === day.value)?.label ?? '')
function next() {
  error.value = ''
  if (step.value === 1 && (!day.value || !time.value)) { error.value = 'Chọn ngày và giờ bạn muốn đến xem phòng.'; return }
  if (step.value === 2 && (!guest.value.trim() || !/^0\d{9}$/.test(phone.value.replace(/\s/g,'')))) { error.value = 'Điền họ tên và số điện thoại gồm 10 chữ số bắt đầu bằng 0.'; return }
  if (step.value < 3) step.value++
  else sent.value = true
}
watch(screen, () => { notice.value = ''; error.value = ''; menu.value = false; modal.value = ''; if (screen.value === 'booking' && onboardingDemo.registered) { guest.value = onboardingDemo.name; phone.value = onboardingDemo.phone }; if (screen.value === 'rental-return') modal.value = 'rental' }, { immediate: true })
</script>

<template>
  <div class="rb-preview">
    <div class="preview-toolbar"><span><strong>Đợt 2 · Bản xem thử</strong><span class="demo-note"> · Dữ liệu mẫu, chưa kết nối nghiệp vụ thật</span></span><label class="preview-picker">Màn hình<select aria-label="Chọn màn hình mẫu" :value="screen" @change="go(($event.target as HTMLSelectElement).value)"><option v-for="tab in screens" :key="tab.id" :value="tab.id">{{ tab.label }}</option></select></label></div>
    <div class="workspace" :class="{ 'with-sidebar': isOwner, 'sidebar-hidden': collapsed }">
      <button v-if="menu" class="scrim" aria-label="Đóng điều hướng" @click="menu = false"></button>
      <aside v-if="isOwner" :class="{ expanded: menu }">
        <a class="brand" href="/preview-v2" @click.prevent="go('overview')"><img src="/icons/rentbase-mark.svg" alt="" />RentBase</a>
        <button class="drawer-close" aria-label="Đóng menu" @click="menu = false">×</button>
        <p class="side-label">{{ onboardingDemo.property.name }}</p>
        <nav aria-label="Menu chủ trọ"><button :class="{ active: screen === 'overview' }" @click="go('overview')">Tổng quan</button><button :class="{ active: screen === 'rooms' }" @click="go('rooms')">Phòng <b>{{ rooms.length }}</b></button><button :class="{ active: screen === 'approvals' }" @click="go('approvals')">Yêu cầu tham gia <b>{{ onboardingDemo.requests.filter(r => r.status === 'pending').length }}</b></button><button :class="{ active: screen === 'invite' }" @click="go('invite')">Mã mời khu trọ</button></nav>
        <div class="side-bottom"><button class="side-preview" @click="go('find')">Xem trang tìm phòng ↗</button><div class="identity"><span class="avatar">AD</span><div><strong>Chủ trọ mẫu</strong><small>Chỉ quản lý khu đang chọn</small></div></div></div>
      </aside>
      <div class="work-main">
        <header class="topbar"><div v-if="isOwner" class="breadcrumbs"><button class="menu-button" aria-label="Mở menu" @click="toggleMenu">☰</button><span>Chủ trọ</span><span>/</span><strong>{{ screenLabel.split(' · ').at(-1) }}</strong></div><a v-else class="brand light" href="/preview-v2?screen=find" @click.prevent="go('find')"><img src="/icons/rentbase-mark.svg" alt="" />RentBase</a><div class="top-right"><template v-if="!isOwner"><button class="quiet" @click="go('find')">Tìm phòng</button><button class="quiet" @click="go('join')">Nhập mã</button><button class="quiet" @click="go(onboardingDemo.registered ? 'status' : 'register')">{{ onboardingDemo.registered ? 'Khu trọ của tôi' : 'Đăng ký' }}</button></template><template v-else><span class="avatar">AD</span><span class="top-name">Chủ trọ mẫu</span></template></div></header>
        <main id="preview-content">
          <p v-if="notice" class="notice" role="status">{{ notice }}<button aria-label="Đóng thông báo" @click="notice = ''">×</button></p>
          <OnboardingPreview v-if="extraScreens.includes(screen)" :screen="screen" :rooms="rooms" @go="go" @receive="receiveRoom" />
          <template v-else-if="screen === 'rooms'">
            <div class="page-heading"><div><p class="eyebrow">KHÔNG GIAN SỐNG, QUẢN LÝ GỌN GÀNG</p><h1>Phòng của nhà trọ</h1><p>Tình trạng phòng và các thao tác cần dùng, tại một nơi.</p></div><button class="primary" @click="open('new')">＋ Thêm phòng</button></div>
            <div class="metrics"><button @click="filter = ''"><span>Tổng số phòng</span><strong>{{ rooms.length }}<small> phòng</small></strong></button><button @click="filter = 'Còn trống'"><span><i class="dot teal"></i>Còn trống</span><strong>{{ rooms.filter(r => r.state === 'Còn trống').length }}<small> phòng</small></strong></button><button @click="filter = 'Đang ở'"><span><i class="dot dark"></i>Đang ở</span><strong>{{ rooms.filter(r => r.state === 'Đang ở').length }}<small> phòng</small></strong></button><button @click="filter = 'Bảo trì'"><span><i class="dot amber"></i>Bảo trì</span><strong>{{ rooms.filter(r => r.state === 'Bảo trì').length }}<small> phòng</small></strong></button></div>
            <section class="panel room-panel"><div class="section-toolbar"><h2>Danh sách phòng <span class="count">{{ visible.length }}</span></h2><div class="filters"><label><span class="sr-only">Tìm số phòng</span><input v-model="search" placeholder="Tìm số phòng…" type="search" /></label><label><span class="sr-only">Tình trạng phòng</span><select v-model="filter"><option value="">Tất cả trạng thái</option><option>Còn trống</option><option>Đang ở</option><option>Bảo trì</option></select></label></div></div>
              <div class="room-row table-head" aria-hidden="true"><span>PHÒNG</span><span>TÌNH TRẠNG</span><span>NGƯỜI Ở</span><span>GIÁ / THÁNG</span><span>THAO TÁC</span></div>
              <article v-for="room in visible" :key="room.id" class="room-row"><div class="room-title"><span class="room-icon">{{ room.name.slice(0,1) }}</span><div><h3>{{ room.name }}</h3><small>{{ room.floor }} · {{ room.area }} m²</small></div></div><span class="badge" :class="room.pending ? 'warn' : room.state === 'Còn trống' ? 'free' : room.state === 'Bảo trì' ? 'warn' : 'neutral'">{{ room.pending ? 'Chờ xóa · 3 ngày' : room.state }}</span><span class="occupants">{{ room.residents }}<span class="muted"> / {{ room.capacity }} người</span></span><strong class="rent">{{ money(room.price) }}</strong><div class="row-actions"><button @click="open('view', room)">Xem</button><button @click="open('edit', room)">Sửa</button><button v-if="!room.pending" class="danger-text" @click="open('delete', room)">Xóa</button><button v-else @click="room.pending = false; notice = 'Đã hủy xóa phòng trong bản xem thử.'">Hủy xóa</button></div></article>
              <div v-if="!visible.length" class="empty"><h3>Chưa tìm thấy phòng</h3><p>Thử số phòng khác hoặc bỏ bộ lọc.</p><button class="secondary" @click="search = ''; filter = ''">Bỏ bộ lọc</button></div><footer class="list-footer">Hiển thị {{ visible.length }} phòng<span>Dữ liệu minh họa</span></footer>
            </section>
          </template>

          <template v-else-if="screen === 'invoice'">
            <a class="back" href="/preview-v2?screen=status">← Hóa đơn của tôi</a><div class="page-heading"><div><p class="eyebrow">PHÒNG A101</p><h1>Hóa đơn tháng 11</h1><p>Mã HD-202611-001 · Phát hành 01/11/2026</p></div><span class="badge warn">Chưa thanh toán</span></div>
            <div class="invoice-layout"><section class="panel invoice-paper"><div class="paper-head"><h2>Chi tiết tiền phòng</h2><span>11/2026</span></div><div class="bill-line" v-for="line in [{name:'Tiền phòng', detail:'01/11 – 30/11/2026',amount:2800000},{name:'Điện',detail:'35 kWh × 3.500 đ',amount:122500},{name:'Nước',detail:'4 m³ × 15.000 đ',amount:60000},{name:'Internet',detail:'Theo phòng / tháng',amount:100000}]" :key="line.name"><div><strong>{{ line.name }}</strong><small>{{ line.detail }}</small></div><strong>{{ money(line.amount) }}</strong></div><div class="bill-total"><span>Tổng hóa đơn</span><strong>3.082.500 đ</strong></div><div class="bill-line"><span>Đã thanh toán</span><span>0 đ</span></div><details><summary>Lịch sử thanh toán</summary><p>Hóa đơn mẫu chưa ghi nhận thanh toán.</p></details></section>
              <section class="payment-card"><span class="eyebrow">SỐ TIỀN CÒN PHẢI TRẢ</span><p class="amount">3.082.500 <small>đ</small></p><div class="due"><span>Hạn thanh toán</span><strong>20/11/2026</strong></div><button class="primary" @click="open('payment')">Thanh toán chuyển khoản <span>→</span></button><p>Trạng thái được cập nhật khi hệ thống xác nhận giao dịch.</p><div class="payment-help"><strong>Cần kiểm tra khoản thu?</strong><p>Đối chiếu chi tiết bên cạnh trước khi thanh toán.</p></div></section></div>
          </template>

          <template v-else-if="(screen === 'find' || screen === 'rental-return')">
            <div class="find-heading"><div><p class="eyebrow">MỘT NƠI ĐỂ BẮT ĐẦU</p><h1>Tìm căn phòng<br />bạn muốn trở về.</h1><p>Xem thông tin rõ ràng. Chọn giờ đến xem phù hợp với bạn.</p></div><div class="search-card"><label>Ngân sách mỗi tháng<select v-model="budget"><option value="">Tất cả mức giá</option><option value="3000000">Đến 3 triệu đồng</option><option value="3500000">Đến 3,5 triệu đồng</option></select></label><span>{{ available.length }} phòng đang sẵn sàng đón bạn</span></div></div>
            <div class="property-grid"><article v-for="room in available" :key="room.id" class="property-card"><button class="photo-button" :aria-label="`Xem phòng ${room.name}`" @click="open('view', room)"><img :src="`/design-preview/${room.photo}`" :alt="`Nội thất minh họa phòng ${room.name}`" /><span class="photo-label">Còn trống</span></button><div class="property-content"><div class="property-top"><h2>Phòng {{ room.name }}</h2><span>{{ room.floor }}</span></div><p>{{ room.area }} m² <span>·</span> Tối đa {{ room.capacity }} người</p><div class="features"><span>Cửa sổ thoáng</span><span>Internet</span></div><div class="property-bottom"><strong>{{ money(room.price) }}<small>/ tháng</small></strong><button class="primary" @click="book(room)">Đặt lịch xem →</button></div></div></article></div>
            <p class="photo-credit">Ảnh nội thất minh họa từ Unsplash. Giá và tiện ích là dữ liệu mẫu.</p>
          </template>

          <template v-else>
            <button class="back" @click="go('find')">← Danh sách phòng</button><div class="page-heading"><div><p class="eyebrow">HẸN GẶP TẠI CĂN PHÒNG MỚI</p><h1>Đặt lịch xem phòng</h1><p>Chọn thời gian, chủ trọ sẽ xác nhận lịch hẹn của bạn.</p></div></div>
            <div class="booking-layout"><section class="panel booking-form"><template v-if="!sent"><ol class="steps"><li v-for="(label,index) in ['Chọn giờ','Thông tin','Xác nhận']" :key="label" :class="{ current: step === index+1, done: step > index+1 }"><span>{{ step > index+1 ? '✓' : index+1 }}</span>{{ label }}</li></ol><form @submit.prevent="next"><template v-if="step === 1"><h2>Bạn muốn đến khi nào?</h2><p class="muted">Các giờ dưới đây là lịch minh họa cho bản thiết kế.</p><fieldset><legend>Chọn ngày</legend><div class="date-options"><label v-for="date in dates" :key="date.value" :class="{ selected: day === date.value }"><input v-model="day" type="radio" name="day" :value="date.value" />{{ date.label }}</label></div></fieldset><fieldset><legend>Chọn giờ</legend><div class="time-options"><label v-for="slot in ['09:00','10:30','14:00','15:30','17:00']" :key="slot" :class="{ selected: time === slot }"><input v-model="time" type="radio" name="time" :value="slot" />{{ slot }}</label></div></fieldset></template><template v-else-if="step === 2"><h2>Thông tin liên hệ</h2><label>Họ và tên<input v-model="guest" autocomplete="name" placeholder="Nhập họ tên của bạn" maxlength="100" /></label><label>Số điện thoại<input v-model="phone" type="tel" autocomplete="tel" placeholder="Số điện thoại liên hệ" maxlength="15" /></label><p class="muted">Chủ trọ dùng thông tin này để liên hệ về lịch hẹn.</p></template><template v-else><h2>Kiểm tra lịch hẹn</h2><dl class="review"><div><dt>Phòng muốn xem</dt><dd>{{ selected.name }}</dd></div><div><dt>Thời gian</dt><dd>{{ dayLabel }} · {{ time }}</dd></div><div><dt>Người liên hệ</dt><dd>{{ guest }}</dd></div><div><dt>Điện thoại</dt><dd>{{ phone }}</dd></div></dl><p class="muted">Lịch xem cần chủ trọ xác nhận. Việc thuê phòng được trao đổi sau khi bạn đến xem.</p></template><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="form-actions"><button v-if="step > 1" type="button" class="secondary" @click="step--; error = ''">Quay lại</button><button class="primary" type="submit">{{ step === 3 ? 'Gửi lịch hẹn mẫu' : 'Tiếp tục' }} →</button></div></form></template><div v-else class="confirmation" role="status"><span class="success-mark">✓</span><p class="eyebrow">ĐÃ HOÀN TẤT THAO TÁC THỬ</p><h2>Lịch hẹn của bạn đã sẵn sàng</h2><p>Phòng {{ selected.name }} · {{ dayLabel }} lúc {{ time }}</p><span class="badge warn">Chờ chủ trọ xác nhận · mô phỏng</span><p>Đây là bản xem thử. Lịch hẹn chưa được gửi đến chủ trọ.</p><button class="secondary" @click="sent = false; step = 1">Chỉnh lại lịch mẫu</button></div></section><section class="booking-room"><img :src="`/design-preview/${selected.photo}`" alt="Ảnh phòng minh họa" /><div><span class="badge free">Còn trống</span><h2>Phòng {{ selected.name }}</h2><p>{{ selected.floor }} · {{ selected.area }} m² · {{ selected.capacity }} người</p><strong>{{ money(selected.price) }}<small> / tháng</small></strong><hr /><p>Đến xem không gian thực tế, trao đổi chi phí và ngày nhận phòng với chủ trọ.</p></div></section></div>
          </template>
        </main><footer class="page-footer"><span>RentBase</span><span>Thiết kế thử · Thông tin được giữ trong phiên xem</span></footer>
      </div>
    </div>
    <UiDialog :open="!!modal" :title="modalTitle" @update:open="value => { if (!value) modal = '' }"><div class="preview-dialog">
      <form v-if="modal === 'edit' || modal === 'new'" @submit.prevent="save"><label>Số phòng<input v-model="draftName" maxlength="30" required /></label><label>Giá thuê mẫu / tháng<input v-model.number="draftPrice" type="number" min="0" required /></label><p v-if="error" role="alert">{{ error }}</p><button class="primary" type="submit">Lưu phòng mẫu</button></form>
      <template v-else-if="modal === 'view'"><img class="detail-photo" :src="`/design-preview/${selected.photo}`" alt="Nội thất phòng minh họa" /><p>{{ selected.floor }} · {{ selected.area }} m² · Tối đa {{ selected.capacity }} người</p><h3>{{ money(selected.price) }} / tháng</h3><p>{{ selected.state }}{{ selected.pending ? ' · Đang chờ xóa' : '' }}</p><button v-if="screen === 'rooms'" class="primary" @click="open('edit')">Sửa thông tin</button><div v-else class="public-actions"><button class="primary" @click="book(selected)">Đặt lịch xem phòng</button><button class="secondary" @click="requestRental">Gửi yêu cầu thuê</button></div></template>
      <template v-else-if="modal === 'delete'"><p>Phòng {{ selected.name }} sẽ chuyển sang trạng thái chờ xóa 3 ngày trong bản xem thử.</p><p>Bạn có thể bấm Hủy xóa tại danh sách. Bản thiết kế này chỉ mô phỏng trạng thái chờ.</p><button class="danger-button" @click="queueDelete">Xác nhận chờ xóa</button></template>
      <form v-else-if="modal === 'rental'" @submit.prevent="sendRental"><h3>Phòng {{ selected.name }}</h3><p>Chủ trọ sẽ liên hệ để xác nhận. Yêu cầu chưa giữ phòng và chưa phát sinh tiền thuê.</p><label>Ngày dự kiến nhận phòng<input v-model="rentalDate" type="date" required /></label><label>Số người dự kiến<input v-model.number="rentalPeople" type="number" min="1" :max="selected.capacity" required /></label><p v-if="error" role="alert">{{ error }}</p><button class="primary" type="submit">Gửi yêu cầu thuê mẫu</button></form>
      <template v-else><p>Bước tiếp theo sẽ mở thanh toán payOS cho đúng hóa đơn.</p><p>Trong bản thiết kế, nút này dùng để xem vị trí và cách trình bày thanh toán. Chưa có giao dịch được tạo.</p><button class="secondary" @click="modal = ''">Quay lại hóa đơn mẫu</button></template>
    </div><template #actions><button class="secondary" @click="modal = ''">Đóng</button></template></UiDialog>
  </div>
</template>

